function validate(input) {
  const [nums, target] = input;
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10^4 numbers.';
  for (let i = 0; i < nums.length; i++) {
    if (!Number.isInteger(nums[i]) || nums[i] < -10000 || nums[i] > 10000) return 'Each value of nums is an integer from -10^4 to 10^4.';
    if (i > 0 && nums[i] < nums[i - 1]) return 'nums must be sorted in non-decreasing order.';
  }
  if (!Number.isInteger(target) || target < -10000 || target > 10000) return 'target is an integer from -10^4 to 10^4.';
  return null;
}

