function adapt(input, solve, kit) {
  const [nums, target] = input;
  if (typeof nums.upperBound !== 'function') throw new Error('Arrays have no upperBound method yet: assign a function to Array.prototype.upperBound.');
  const before = JSON.stringify(nums);
  const index = nums.upperBound(target);
  if (!Number.isInteger(index)) throw new Error('upperBound must return an index (an integer), or -1.');
  if (JSON.stringify(nums) !== before) throw new Error('upperBound must not change the array.');
  kit.trace(`nums.upperBound(${target}) returns ${index}`);
  return index;
}

