Array.prototype.upperBound = function (target) {
  let left = 0;
  let right = this.length;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (this[mid] <= target) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  const last = left - 1;
  if (last >= 0 && this[last] === target) {
    return last;
  }
  return -1;
};

