function generate(rand, size) {
  const small = size === 'small';
  const length = small ? 1 + Math.floor(rand() * 7) : 1500 + Math.floor(rand() * 501);
  const spread = small ? 1 + Math.floor(rand() * 6) : Math.floor(rand() * 10001);
  const nums = Array.from({ length }, () => Math.floor(rand() * (2 * spread + 1)) - spread).sort((a, b) => a - b);
  const roll = rand();
  let target;
  if (roll < 0.6) target = nums[Math.floor(rand() * length)];
  else if (roll < 0.7) target = nums[0] - 1 - Math.floor(rand() * 3);
  else if (roll < 0.8) target = nums[length - 1] + 1 + Math.floor(rand() * 3);
  else target = Math.floor(rand() * (2 * spread + 3)) - spread - 1;
  target = Math.max(-10000, Math.min(10000, target));
  return [nums, target];
}
